HTML_CONTENT = '<!DOCTYPE html>\n<html lang="zh-CN" class="dark">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n    <!-- PWA Web App Support -->\n    <meta name="apple-mobile-web-app-capable" content="yes">\n    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n    <link rel="manifest" href="manifest.json">\n    <!-- 关键：绕过平台防盗链 Referer 限制 -->\n    <meta name="referrer" content="no-referrer">\n    <title>OmniMedia Pro · 全能短视频与实况图集去水印 App</title>\n    \n    <!-- CDN 依赖：TailwindCSS, Vue 3, Lucide Icons, JSZip, Canvas Confetti -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            darkMode: \'class\',\n            theme: {\n                extend: {\n                    colors: {\n                        brand: {\n                            50: \'#eef2ff\',\n                            100: \'#e0e7ff\',\n                            500: \'#6366f1\',\n                            600: \'#4f46e5\',\n                            700: \'#4338ca\',\n                            900: \'#1e1b4b\',\n                        }\n                    }\n                }\n            }\n        }\n    </script>\n    <script src="https://unpkg.com/vue@3/dist/vue.global.prod.js"></script>\n    <script src="https://unpkg.com/lucide@latest"></script>\n    <script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script>\n    <script src="https://cdn.jsdelivr.net/npm/canvas-confetti@1.9.2/dist/confetti.browser.min.js"></script>\n\n    <style>\n        /* 4大风格专属样式 */\n\n        /* 1. 极光流光 (Aurora Glass) */\n        .theme-aurora {\n            --bg-color: #0b0f19;\n            --text-color: #f1f5f9;\n            --card-bg: rgba(30, 41, 59, 0.75);\n            --card-border: rgba(255, 255, 255, 0.1);\n            --primary-gradient: linear-gradient(135deg, #6366f1 0%, #a855f7 50%, #ec4899 100%);\n            --btn-bg: #6366f1;\n            --btn-hover: #4f46e5;\n            --accent-glow: rgba(99, 102, 241, 0.3);\n        }\n\n        /* 2. 苹果极简白 (Apple Clean) */\n        .theme-apple {\n            --bg-color: #f8fafc;\n            --text-color: #0f172a;\n            --card-bg: rgba(255, 255, 255, 0.95);\n            --card-border: rgba(226, 232, 240, 0.9);\n            --primary-gradient: linear-gradient(135deg, #0284c7 0%, #38bdf8 100%);\n            --btn-bg: #0284c7;\n            --btn-hover: #0369a1;\n            --accent-glow: rgba(2, 132, 199, 0.2);\n        }\n\n        /* 3. 赛博霓虹 (Cyberpunk Neon) */\n        .theme-cyberpunk {\n            --bg-color: #05050a;\n            --text-color: #e0f2fe;\n            --card-bg: rgba(12, 14, 24, 0.85);\n            --card-border: rgba(6, 182, 212, 0.4);\n            --primary-gradient: linear-gradient(135deg, #00f2fe 0%, #4facfe 50%, #f72585 100%);\n            --btn-bg: #06b6d4;\n            --btn-hover: #0891b2;\n            --accent-glow: rgba(6, 182, 212, 0.4);\n        }\n\n        /* 4. 钛金黑曜 (Titanium Studio) */\n        .theme-titanium {\n            --bg-color: #0c0d10;\n            --text-color: #fef3c7;\n            --card-bg: rgba(23, 23, 28, 0.85);\n            --card-border: rgba(217, 119, 6, 0.3);\n            --primary-gradient: linear-gradient(135deg, #f59e0b 0%, #d97706 50%, #b45309 100%);\n            --btn-bg: #d97706;\n            --btn-hover: #b45309;\n            --accent-glow: rgba(217, 119, 6, 0.3);\n        }\n\n        body {\n            background-color: var(--bg-color);\n            color: var(--text-color);\n            transition: background-color 0.4s ease, color 0.4s ease;\n        }\n\n        .glass-panel {\n            background: var(--card-bg);\n            backdrop-filter: blur(20px);\n            -webkit-backdrop-filter: blur(20px);\n            border: 1px solid var(--card-border);\n            box-shadow: 0 10px 30px -10px var(--accent-glow);\n            transition: all 0.3s ease;\n        }\n\n        .btn-theme-primary {\n            background: var(--primary-gradient);\n            box-shadow: 0 4px 20px -2px var(--accent-glow);\n        }\n\n        .live-badge {\n            background: rgba(0, 0, 0, 0.7);\n            backdrop-filter: blur(8px);\n            border: 1px solid rgba(255, 255, 255, 0.25);\n            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n        }\n        .live-card:hover .live-badge,\n        .live-card.is-active .live-badge {\n            background: rgba(236, 72, 153, 0.95);\n            border-color: rgba(255, 255, 255, 0.8);\n            transform: scale(1.05);\n            box-shadow: 0 0 15px rgba(236, 72, 153, 0.6);\n        }\n    </style>\n</head>\n<body class="theme-aurora min-h-screen selection:bg-indigo-500 selection:text-white relative overflow-x-hidden font-sans">\n\n    <div id="app" class="relative z-10 max-w-6xl mx-auto px-4 py-6 sm:py-10">\n\n        <!-- 顶部导航栏 -->\n        <header class="flex flex-wrap items-center justify-between gap-4 pb-6 mb-8 border-b border-slate-800/80">\n            <div class="flex items-center space-x-3">\n                <div class="w-11 h-11 rounded-2xl flex items-center justify-center shadow-lg transition" :style="{ background: \'var(--primary-gradient)\' }">\n                    <i data-lucide="sparkles" class="w-6 h-6 text-white"></i>\n                </div>\n                <div>\n                    <h1 class="text-xl sm:text-2xl font-bold tracking-tight bg-clip-text text-transparent" :style="{ backgroundImage: \'var(--primary-gradient)\' }">\n                        OmniMedia Pro App\n                    </h1>\n                    <p class="text-xs opacity-70">支持 4K 原画 / 实况图 / 高清图集 1:1 无损提取 · 零后台独立版</p>\n                </div>\n            </div>\n\n            <!-- 右侧功能按键：UI风格切换器 + 历史记录 -->\n            <div class="flex items-center space-x-2 sm:space-x-3">\n                \n                <!-- 🎨 UI 风格实时切换器 -->\n                <div class="relative flex items-center bg-slate-800/80 rounded-xl p-1 border border-slate-700/80">\n                    <button \n                        v-for="t in themeOptions" \n                        :key="t.id"\n                        @click="setTheme(t.id)"\n                        :class="currentTheme === t.id ? \'bg-indigo-600 text-white font-bold shadow-md\' : \'text-slate-400 hover:text-slate-200\'"\n                        class="px-2.5 py-1 text-xs rounded-lg transition flex items-center space-x-1"\n                        :title="t.name"\n                    >\n                        <span>{{ t.icon }}</span>\n                        <span class="hidden md:inline">{{ t.name }}</span>\n                    </button>\n                </div>\n\n                <button @click="showHistory = true" class="px-3 py-1.5 text-xs sm:text-sm font-medium rounded-xl bg-slate-800/80 hover:bg-slate-700 text-slate-300 hover:text-white border border-slate-700/60 transition flex items-center space-x-1.5">\n                    <i data-lucide="history" class="w-4 h-4"></i>\n                    <span>历史 ({{ historyList.length }})</span>\n                </button>\n                \n                <button @click="showHelp = true" class="p-2 text-slate-400 hover:text-white rounded-xl bg-slate-800/60 hover:bg-slate-700 border border-slate-700/60 transition" title="使用说明">\n                    <i data-lucide="help-circle" class="w-4 h-4"></i>\n                </button>\n            </div>\n        </header>\n\n        <!-- 主输入区域 -->\n        <div class="glass-panel rounded-2xl p-4 sm:p-7 mb-8 shadow-2xl relative overflow-hidden">\n            <!-- 标签页切换 -->\n            <div class="flex items-center space-x-4 mb-5 border-b border-slate-700/40 pb-3">\n                <button @click="tab = \'single\'" :class="tab === \'single\' ? \'font-bold border-b-2 border-indigo-500 pb-1 text-indigo-400\' : \'opacity-60 hover:opacity-100\'" class="transition text-sm sm:text-base flex items-center space-x-1.5">\n                    <i data-lucide="link" class="w-4 h-4"></i>\n                    <span>单链接解析</span>\n                </button>\n                <button @click="tab = \'batch\'" :class="tab === \'batch\' ? \'font-bold border-b-2 border-indigo-500 pb-1 text-indigo-400\' : \'opacity-60 hover:opacity-100\'" class="transition text-sm sm:text-base flex items-center space-x-1.5">\n                    <i data-lucide="layers" class="w-4 h-4"></i>\n                    <span>批量并发解析</span>\n                </button>\n            </div>\n\n            <!-- 单链接解析表单 -->\n            <div v-if="tab === \'single\'" class="space-y-4">\n                <div class="relative">\n                    <textarea \n                        v-model="inputUrl" \n                        rows="3" \n                        placeholder="在此粘贴抖音或快手分享链接，如：7.12 复制打开抖音，看看【某个作品】https://v.douyin.com/xxxx/..." \n                        class="w-full bg-slate-900/90 text-slate-100 placeholder-slate-500 text-sm sm:text-base rounded-xl p-4 border border-slate-700/80 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 focus:outline-none transition resize-none"\n                        @keydown.enter.ctrl="handleParse"\n                    ></textarea>\n                </div>\n\n                <div class="flex flex-wrap items-center justify-between gap-3">\n                    <div class="flex items-center space-x-2 text-xs opacity-75">\n                        <span class="inline-flex items-center px-2 py-0.5 rounded bg-pink-500/10 text-pink-400 border border-pink-500/20">抖音 4K/实况图/图集</span>\n                        <span class="inline-flex items-center px-2 py-0.5 rounded bg-orange-500/10 text-orange-400 border border-orange-500/20">快手 4K/图集</span>\n                    </div>\n\n                    <div class="flex items-center space-x-2">\n                        <button @click="pasteClipboard" class="px-3.5 py-2 text-xs sm:text-sm font-medium rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 transition flex items-center space-x-1.5">\n                            <i data-lucide="clipboard-paste" class="w-4 h-4"></i>\n                            <span>一键粘贴</span>\n                        </button>\n                        <button @click="inputUrl = \'\'" v-if="inputUrl" class="px-3 py-2 text-xs sm:text-sm font-medium rounded-xl bg-slate-800/80 hover:bg-slate-700 text-slate-400 hover:text-white transition">\n                            清空\n                        </button>\n                        <button \n                            @click="handleParse" \n                            :disabled="isParsing" \n                            class="btn-theme-primary px-6 py-2.5 text-xs sm:text-sm font-bold rounded-xl text-white transition disabled:opacity-50 flex items-center space-x-2 cursor-pointer shadow-lg"\n                        >\n                            <svg v-if="isParsing" class="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">\n                                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>\n                                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>\n                            </svg>\n                            <i v-else data-lucide="zap" class="w-4 h-4"></i>\n                            <span>{{ isParsing ? \'正在极速解析...\' : \'一键无损解析\' }}</span>\n                        </button>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 批量解析表单 -->\n            <div v-else class="space-y-4">\n                <textarea \n                    v-model="batchText" \n                    rows="5" \n                    placeholder="在此粘贴包含多个分享链接的大段文字，每行一个或混合在文案中均可，系统会自动智能提取全部链接并并发解析..." \n                    class="w-full bg-slate-900/90 text-slate-100 placeholder-slate-500 text-sm sm:text-base rounded-xl p-4 border border-slate-700/80 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 focus:outline-none transition resize-none"\n                ></textarea>\n\n                <div class="flex items-center justify-between">\n                    <button @click="pasteClipboard" class="px-3.5 py-2 text-xs sm:text-sm font-medium rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 transition flex items-center space-x-1.5">\n                        <i data-lucide="clipboard-paste" class="w-4 h-4"></i>\n                        <span>粘贴大段文本</span>\n                    </button>\n                    <button \n                        @click="handleBatchParse" \n                        :disabled="isParsing" \n                        class="btn-theme-primary px-6 py-2.5 text-xs sm:text-sm font-bold rounded-xl text-white transition disabled:opacity-50 flex items-center space-x-2"\n                    >\n                        <i data-lucide="play" class="w-4 h-4"></i>\n                        <span>{{ isParsing ? \'正在并发解析中...\' : \'开始批量并发解析\' }}</span>\n                    </button>\n                </div>\n            </div>\n\n            <!-- 进度提示 -->\n            <div v-if="statusMsg" class="mt-4 p-3 rounded-xl bg-indigo-950/50 border border-indigo-800/40 text-xs sm:text-sm text-indigo-300 flex items-center space-x-2">\n                <i data-lucide="info" class="w-4 h-4 text-indigo-400 shrink-0"></i>\n                <span>{{ statusMsg }}</span>\n            </div>\n        </div>\n\n        <!-- 单项解析结果展示 -->\n        <div v-if="result" id="result-container" class="glass-panel rounded-2xl p-5 sm:p-8 mb-8 shadow-2xl transition-all">\n            \n            <!-- 头部作者信息与统计 -->\n            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-slate-800/60">\n                <div class="flex items-center space-x-3.5">\n                    <img :src="result.author.avatar || \'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&h=100&fit=crop\'" class="w-12 h-12 rounded-full object-cover border-2 border-indigo-500/40 shadow-md">\n                    <div>\n                        <div class="flex items-center space-x-2">\n                            <span class="font-bold text-base sm:text-lg">{{ result.author.nickname }}</span>\n                            <span class="px-2 py-0.5 text-xs font-semibold rounded-full bg-pink-500/20 text-pink-400 border border-pink-500/30">\n                                {{ result.platformName }}\n                            </span>\n                            <span class="px-2 py-0.5 text-xs font-semibold rounded-full bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">\n                                {{ getMediaTypeBadge(result) }}\n                            </span>\n                        </div>\n                        <p class="text-xs opacity-60 mt-0.5">ID: {{ result.author.uid || result.itemId }}</p>\n                    </div>\n                </div>\n\n                <!-- 统计数据 -->\n                <div class="flex items-center space-x-4 text-xs opacity-75">\n                    <div class="flex items-center space-x-1">\n                        <i data-lucide="heart" class="w-3.5 h-3.5 text-red-400"></i>\n                        <span>{{ formatNumber(result.stats.likes) }} 赞</span>\n                    </div>\n                    <div class="flex items-center space-x-1">\n                        <i data-lucide="message-circle" class="w-3.5 h-3.5 text-blue-400"></i>\n                        <span>{{ formatNumber(result.stats.comments) }} 评论</span>\n                    </div>\n                    <div class="flex items-center space-x-1">\n                        <i data-lucide="bookmark" class="w-3.5 h-3.5 text-yellow-400"></i>\n                        <span>{{ formatNumber(result.stats.collects) }} 收藏</span>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 作品文案 -->\n            <div class="my-5">\n                <p class="text-sm sm:text-base leading-relaxed select-text font-normal opacity-90">\n                    {{ result.title }}\n                </p>\n            </div>\n\n            <!-- 1. 视频类型展示 -->\n            <div v-if="result.mediaType === \'video\' && result.videoUrl" class="space-y-5">\n                <div class="relative rounded-2xl overflow-hidden bg-black/90 max-h-[560px] flex items-center justify-center border border-slate-800 shadow-inner">\n                    <video \n                        :src="selectedQuality ? selectedQuality.url : result.videoUrl" \n                        controls \n                        playsinline \n                        preload="metadata"\n                        class="w-full max-h-[560px] object-contain"\n                    ></video>\n                </div>\n\n                <!-- 清晰度切换 & 下载工具栏 -->\n                <div class="flex flex-wrap items-center justify-between gap-4 p-4 rounded-xl bg-slate-900/80 border border-slate-800/80">\n                    \n                    <!-- 清晰度档位 -->\n                    <div class="flex items-center space-x-2">\n                        <span class="text-xs opacity-70 font-medium">清晰度:</span>\n                        <div class="flex flex-wrap gap-1.5">\n                            <button \n                                v-for="(q, idx) in result.qualities" \n                                :key="idx"\n                                @click="selectedQuality = q"\n                                :class="selectedQuality && selectedQuality.url === q.url ? \'bg-indigo-600 text-white font-bold\' : \'bg-slate-800 text-slate-300 hover:bg-slate-700\'"\n                                class="px-2.5 py-1 text-xs rounded-lg transition"\n                            >\n                                {{ q.label }}\n                            </button>\n                        </div>\n                    </div>\n\n                    <!-- 操作按键 -->\n                    <div class="flex flex-wrap items-center gap-2">\n                        <button @click="downloadFile(selectedQuality ? selectedQuality.url : result.videoUrl, `[${result.platformName}]_${result.author.nickname}_${result.title.slice(0, 20)}.mp4`)" class="btn-theme-primary px-4 py-2 text-xs sm:text-sm font-bold rounded-xl text-white transition flex items-center space-x-1.5 cursor-pointer">\n                            <i data-lucide="download" class="w-4 h-4"></i>\n                            <span>下载 4K/最高清视频</span>\n                        </button>\n                        \n                        <button v-if="result.musicUrl" @click="downloadFile(result.musicUrl, `BGM_${result.musicTitle || \'音频\'}.mp3`)" class="px-3 py-2 text-xs sm:text-sm font-medium rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 transition flex items-center space-x-1.5">\n                            <i data-lucide="music" class="w-4 h-4 text-pink-400"></i>\n                            <span>下载原声 BGM</span>\n                        </button>\n\n                        <button @click="copyLink(selectedQuality ? selectedQuality.url : result.videoUrl)" class="px-3 py-2 text-xs sm:text-sm font-medium rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 transition" title="复制直链">\n                            <i data-lucide="copy" class="w-4 h-4"></i>\n                        </button>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 2. 实况照片 (Live Photo) 专属展示与交互 -->\n            <div v-else-if="result.mediaType === \'live_photo\'" class="space-y-6">\n                \n                <div class="flex flex-wrap items-center justify-between gap-3 p-4 rounded-xl bg-pink-950/20 border border-pink-800/40">\n                    <div class="flex items-center space-x-2">\n                        <span class="w-2.5 h-2.5 rounded-full bg-pink-500 animate-pulse"></span>\n                        <span class="text-sm font-bold text-pink-400">抖音实况照片 (Live Photo) 共 {{ result.livePhotos.length }} 张</span>\n                        <span class="text-xs opacity-60 hidden sm:inline">（电脑鼠标悬停 / 手机长按卡片即可实时预览动态实况）</span>\n                    </div>\n\n                    <!-- 一键打包全部实况与原图 -->\n                    <button \n                        @click="downloadPackZip(result)" \n                        :disabled="isZipping" \n                        class="btn-theme-primary px-4 py-2 text-xs sm:text-sm font-bold rounded-xl text-white transition disabled:opacity-50 flex items-center space-x-1.5"\n                    >\n                        <i data-lucide="package-check" class="w-4 h-4"></i>\n                        <span>{{ isZipping ? \'正在打包 ZIP...\' : \'一键打包下载全部实况图 (ZIP)\' }}</span>\n                    </button>\n                </div>\n\n                <!-- 实况网格列表 -->\n                <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5">\n                    <div \n                        v-for="(lp, idx) in result.livePhotos" \n                        :key="idx"\n                        class="live-card group relative rounded-2xl overflow-hidden bg-slate-900 border border-slate-800 shadow-xl transition hover:border-pink-500/50"\n                        @mouseenter="playLive(idx)"\n                        @mouseleave="stopLive(idx)"\n                        @touchstart="playLive(idx)"\n                        @touchend="stopLive(idx)"\n                    >\n                        <div class="aspect-[3/4] relative overflow-hidden bg-black/40">\n                            <!-- 静态原图 -->\n                            <img :src="lp.imageUrl" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" loading="lazy">\n                            \n                            <!-- 动态短片 (Hover / Touch 时叠加播放) -->\n                            <video \n                                v-if="lp.videoUrl"\n                                :ref="el => setLiveVideoRef(el, idx)"\n                                :src="lp.videoUrl"\n                                loop\n                                muted\n                                playsinline\n                                preload="none"\n                                class="absolute inset-0 w-full h-full object-cover transition-opacity duration-300"\n                                :class="activeLiveIdx === idx ? \'opacity-100 z-10\' : \'opacity-0 pointer-events-none\'"\n                            ></video>\n\n                            <!-- 实况 LIVE 徽章 -->\n                            <div class="absolute top-3 left-3 z-20 live-badge px-2.5 py-1 rounded-full text-[11px] font-bold text-white flex items-center space-x-1.5 pointer-events-none">\n                                <span class="w-2 h-2 rounded-full bg-pink-400" :class="activeLiveIdx === idx ? \'animate-ping\' : \'\'"></span>\n                                <span>LIVE 实况 {{ idx + 1 }}</span>\n                            </div>\n\n                            <!-- 全屏预览放大按键 -->\n                            <button @click.stop="openLightbox(result.livePhotos.map(p => p.imageUrl), idx)" class="absolute top-3 right-3 z-20 p-2 rounded-full bg-black/60 hover:bg-black/80 text-white backdrop-blur-sm transition opacity-0 group-hover:opacity-100">\n                                <i data-lucide="maximize-2" class="w-4 h-4"></i>\n                            </button>\n                        </div>\n\n                        <!-- 底部下载操作栏 -->\n                        <div class="p-3.5 bg-slate-900/90 flex items-center justify-between gap-2 border-t border-slate-800">\n                            <button @click="downloadFile(lp.imageUrl, `[实况原图]_${result.author.nickname}_${idx+1}.jpg`)" class="flex-1 py-1.5 text-xs font-medium rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 transition text-center flex items-center justify-center space-x-1">\n                                <i data-lucide="image" class="w-3.5 h-3.5 text-indigo-400"></i>\n                                <span>存静态图</span>\n                            </button>\n                            <button v-if="lp.videoUrl" @click="downloadFile(lp.videoUrl, `[实况动图]_${result.author.nickname}_${idx+1}.mp4`)" class="flex-1 py-1.5 text-xs font-bold rounded-lg bg-pink-600/80 hover:bg-pink-600 text-white transition text-center flex items-center justify-center space-x-1 shadow-sm">\n                                <i data-lucide="video" class="w-3.5 h-3.5"></i>\n                                <span>存动态视频</span>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 3. 高清图集 (Album) 专属展示 -->\n            <div v-else-if="result.mediaType === \'images\' && result.images.length > 0" class="space-y-6">\n                \n                <div class="flex flex-wrap items-center justify-between gap-3 p-4 rounded-xl bg-indigo-950/20 border border-indigo-800/40">\n                    <div class="flex items-center space-x-2">\n                        <span class="text-sm font-bold text-indigo-300">高清无水印图集 共 {{ result.images.length }} 张原图</span>\n                        <span class="text-xs opacity-60 hidden sm:inline">（点击图片可全屏大图预览）</span>\n                    </div>\n\n                    <button \n                        @click="downloadPackZip(result)" \n                        :disabled="isZipping" \n                        class="btn-theme-primary px-4 py-2 text-xs sm:text-sm font-bold rounded-xl text-white transition disabled:opacity-50 flex items-center space-x-1.5"\n                    >\n                        <i data-lucide="package-check" class="w-4 h-4"></i>\n                        <span>{{ isZipping ? \'正在打包 ZIP...\' : \'一键打包全部高清原图 (ZIP)\' }}</span>\n                    </button>\n                </div>\n\n                <!-- 图集网格 -->\n                <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">\n                    <div \n                        v-for="(img, idx) in result.images" \n                        :key="idx" \n                        class="group relative rounded-xl overflow-hidden bg-slate-900 border border-slate-800 hover:border-indigo-500/50 transition shadow-lg aspect-square"\n                    >\n                        <img \n                            :src="img" \n                            class="w-full h-full object-cover cursor-pointer transition-transform duration-300 group-hover:scale-105" \n                            @click="openLightbox(result.images, idx)"\n                            loading="lazy"\n                        >\n                        <div class="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end justify-between p-3 pointer-events-none">\n                            <span class="text-xs font-bold text-white">#{{ idx + 1 }}</span>\n                            <button @click.stop="downloadFile(img, `[高清图集]_${result.author.nickname}_${idx+1}.jpg`)" class="pointer-events-auto p-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white shadow transition">\n                                <i data-lucide="download" class="w-3.5 h-3.5"></i>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 背景音乐 BGM 条 -->\n            <div v-if="result.musicUrl" class="mt-6 pt-5 border-t border-slate-800/80 flex flex-wrap items-center justify-between gap-3">\n                <div class="flex items-center space-x-3">\n                    <div class="w-9 h-9 rounded-full bg-pink-500/10 border border-pink-500/30 flex items-center justify-center">\n                        <i data-lucide="disc" class="w-4 h-4 text-pink-400"></i>\n                    </div>\n                    <div>\n                        <p class="text-xs sm:text-sm font-semibold">{{ result.musicTitle || \'作品背景原声音频\' }}</p>\n                        <p class="text-xs opacity-60">{{ result.musicAuthor || \'原作者\' }}</p>\n                    </div>\n                </div>\n                <div class="flex items-center space-x-2">\n                    <audio :src="result.musicUrl" controls class="h-8 max-w-[200px] sm:max-w-none opacity-80 hover:opacity-100 transition"></audio>\n                    <button @click="downloadFile(result.musicUrl, `BGM_${result.musicTitle || \'音频\'}.mp3`)" class="p-2 text-xs rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 transition" title="下载音频">\n                        <i data-lucide="download" class="w-4 h-4"></i>\n                    </button>\n                </div>\n            </div>\n\n        </div>\n\n        <!-- 批量解析结果卡片列表 -->\n        <div v-if="batchResults.length > 0" class="space-y-4 mb-8">\n            <div class="flex items-center justify-between pb-2 border-b border-slate-800/60">\n                <h3 class="text-lg font-bold flex items-center space-x-2">\n                    <i data-lucide="check-circle-2" class="w-5 h-5 text-emerald-400"></i>\n                    <span>批量解析完成 (共 {{ batchResults.length }} 项)</span>\n                </h3>\n            </div>\n\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n                <div v-for="(item, idx) in batchResults" :key="idx" class="glass-panel p-4 rounded-xl border border-slate-800 hover:border-slate-700 transition flex space-x-3.5">\n                    <img :src="item.coverUrl || item.images[0] || (item.author && item.author.avatar)" class="w-20 h-24 object-cover rounded-lg bg-slate-900 shrink-0">\n                    <div class="flex-1 flex flex-col justify-between overflow-hidden">\n                        <div>\n                            <div class="flex items-center space-x-2 mb-1">\n                                <span class="px-1.5 py-0.5 text-[10px] rounded bg-indigo-500/20 text-indigo-300">{{ item.platformName }}</span>\n                                <span class="text-xs opacity-75 truncate">{{ item.author ? item.author.nickname : \'\' }}</span>\n                            </div>\n                            <p class="text-xs line-clamp-2 opacity-90">{{ item.title }}</p>\n                        </div>\n                        <div class="flex items-center space-x-2 pt-2">\n                            <button @click="viewBatchItem(item)" class="px-2.5 py-1 text-xs rounded-md bg-slate-800 hover:bg-slate-700 text-slate-200 transition">\n                                查看详情\n                            </button>\n                            <button v-if="item.videoUrl" @click="downloadFile(item.videoUrl, `[${item.platformName}]_${item.title.slice(0, 15)}.mp4`)" class="px-2.5 py-1 text-xs font-bold rounded-md bg-indigo-600 hover:bg-indigo-500 text-white transition">\n                                下载视频\n                            </button>\n                            <button v-else-if="item.images.length" @click="downloadPackZip(item)" class="px-2.5 py-1 text-xs font-bold rounded-md bg-purple-600 hover:bg-purple-500 text-white transition">\n                                打包图集\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- 历史记录抽屉 -->\n        <div v-if="showHistory" class="fixed inset-0 z-50 flex justify-end bg-black/60 backdrop-blur-sm transition-opacity" @click.self="showHistory = false">\n            <div class="w-full max-w-md bg-[#0f172a] h-full p-6 shadow-2xl overflow-y-auto border-l border-slate-800 flex flex-col text-slate-100">\n                <div class="flex items-center justify-between pb-4 mb-4 border-b border-slate-800">\n                    <h3 class="text-lg font-bold flex items-center space-x-2">\n                        <i data-lucide="clock" class="w-5 h-5 text-indigo-400"></i>\n                        <span>解析历史记录</span>\n                    </h3>\n                    <div class="flex items-center space-x-2">\n                        <button @click="clearHistory" class="text-xs text-red-400 hover:text-red-300 transition">清空</button>\n                        <button @click="showHistory = false" class="p-1 rounded-lg text-slate-400 hover:text-white">\n                            <i data-lucide="x" class="w-5 h-5"></i>\n                        </button>\n                    </div>\n                </div>\n\n                <div v-if="historyList.length === 0" class="flex-1 flex flex-col items-center justify-center text-slate-500">\n                    <i data-lucide="inbox" class="w-12 h-12 mb-2 stroke-1"></i>\n                    <p class="text-sm">暂无历史记录</p>\n                </div>\n\n                <div v-else class="space-y-3 flex-1">\n                    <div v-for="(h, idx) in historyList" :key="idx" @click="loadFromHistory(h)" class="p-3 rounded-xl bg-slate-900/90 hover:bg-slate-800 border border-slate-800/80 transition cursor-pointer flex space-x-3 items-center">\n                        <img :src="h.coverUrl || (h.images && h.images[0]) || (h.author && h.author.avatar)" class="w-14 h-14 rounded-lg object-cover bg-black shrink-0">\n                        <div class="flex-1 overflow-hidden">\n                            <div class="flex items-center space-x-1.5 mb-0.5">\n                                <span class="text-[10px] px-1.5 py-0.2 rounded bg-slate-800 text-indigo-400">{{ h.platformName }}</span>\n                                <span class="text-xs font-semibold truncate">{{ h.author ? h.author.nickname : \'\' }}</span>\n                            </div>\n                            <p class="text-xs opacity-75 truncate">{{ h.title }}</p>\n                            <span class="text-[10px] opacity-50">{{ h.savedAt }}</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- 全屏图片 Lightbox 灯箱 -->\n        <div v-if="lightbox.show" class="fixed inset-0 z-50 bg-black/95 flex items-center justify-center select-none" @click.self="lightbox.show = false">\n            <button @click="lightbox.show = false" class="absolute top-5 right-5 p-3 rounded-full bg-slate-800/80 hover:bg-slate-700 text-white z-50">\n                <i data-lucide="x" class="w-6 h-6"></i>\n            </button>\n            <button @click="lightboxPrev" class="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-slate-800/80 hover:bg-slate-700 text-white z-50">\n                <i data-lucide="chevron-left" class="w-6 h-6"></i>\n            </button>\n            <button @click="lightboxNext" class="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-slate-800/80 hover:bg-slate-700 text-white z-50">\n                <i data-lucide="chevron-right" class="w-6 h-6"></i>\n            </button>\n            \n            <div class="max-w-[90vw] max-h-[90vh] flex flex-col items-center">\n                <img :src="lightbox.images[lightbox.index]" class="max-w-full max-h-[85vh] object-contain rounded-lg shadow-2xl">\n                <div class="mt-4 flex items-center space-x-4">\n                    <span class="text-xs opacity-75 font-medium">{{ lightbox.index + 1 }} / {{ lightbox.images.length }}</span>\n                    <button @click="downloadFile(lightbox.images[lightbox.index], `image_${lightbox.index+1}.jpg`)" class="px-3 py-1 text-xs rounded-md bg-indigo-600 hover:bg-indigo-500 text-white">\n                        下载此图\n                    </button>\n                </div>\n            </div>\n        </div>\n\n        <!-- 帮助/说明弹窗 -->\n        <div v-if="showHelp" class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm" @click.self="showHelp = false">\n            <div class="max-w-md w-full glass-panel rounded-2xl p-6 border border-slate-700 space-y-4">\n                <div class="flex items-center justify-between pb-2 border-b border-slate-800">\n                    <h3 class="text-base font-bold flex items-center space-x-2">\n                        <i data-lucide="info" class="w-5 h-5 text-indigo-400"></i>\n                        <span>关于独立版 App</span>\n                    </h3>\n                    <button @click="showHelp = false" class="opacity-60 hover:opacity-100"><i data-lucide="x" class="w-5 h-5"></i></button>\n                </div>\n                <div class="text-xs sm:text-sm opacity-90 space-y-2.5 leading-relaxed">\n                    <p>✨ <strong>零后台：</strong> 采用纯前端客户端解析与防盗链直连技术，无需后台。</p>\n                    <p>🌐 <strong>随时随地使用：</strong> 在任何网络（4G/5G、任意 WiFi、局域网外）下均可使用。</p>\n                    <p>🎨 <strong>4 大主题风格：</strong> 支持极光流光、苹果极简白、赛博霓虹、钛金黑曜实时无缝切换。</p>\n                </div>\n                <button @click="showHelp = false" class="w-full py-2 rounded-xl btn-theme-primary text-white font-medium text-xs sm:text-sm transition">知道了</button>\n            </div>\n        </div>\n\n        <!-- Toast 提示 -->\n        <div v-if="toast.show" class="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-4 py-2.5 rounded-xl shadow-2xl text-xs sm:text-sm font-medium transition-all flex items-center space-x-2" :class="toast.type === \'error\' ? \'bg-red-900/90 text-red-200 border border-red-700\' : \'bg-indigo-900/90 text-indigo-100 border border-indigo-700\'">\n            <i data-lucide="bell" class="w-4 h-4"></i>\n            <span>{{ toast.message }}</span>\n        </div>\n\n    </div>\n\n    <!-- 客户端核心解析脚本 -->\n    <script>\n        const { createApp, ref, onMounted, nextTick } = Vue;\n\n        createApp({\n            setup() {\n                const currentTheme = ref(\'aurora\');\n                const themeOptions = [\n                    { id: \'aurora\', name: \'极光流光\', icon: \'🌌\' },\n                    { id: \'apple\', name: \'苹果极简\', icon: \'🍎\' },\n                    { id: \'cyberpunk\', name: \'赛博霓虹\', icon: \'⚡\' },\n                    { id: \'titanium\', name: \'钛金黑曜\', icon: \'👑\' },\n                ];\n\n                const setTheme = (tId) => {\n                    currentTheme.value = tId;\n                    document.body.className = `theme-${tId} min-h-screen selection:bg-indigo-500 selection:text-white relative overflow-x-hidden font-sans`;\n                    try {\n                        localStorage.setItem(\'omnimedia_theme\', tId);\n                    } catch (e) {}\n                };\n\n                const tab = ref(\'single\');\n                const inputUrl = ref(\'\');\n                const batchText = ref(\'\');\n                const isParsing = ref(false);\n                const statusMsg = ref(\'\');\n                const result = ref(null);\n                const selectedQuality = ref(null);\n                const batchResults = ref([]);\n                const isZipping = ref(false);\n                const showHistory = ref(false);\n                const showHelp = ref(false);\n                const historyList = ref([]);\n                const activeLiveIdx = ref(null);\n                const liveVideoRefs = ref({});\n\n                const lightbox = ref({\n                    show: false,\n                    images: [],\n                    index: 0\n                });\n\n                const toast = ref({ show: false, message: \'\', type: \'info\' });\n                let toastTimer = null;\n\n                const showToast = (msg, type = \'info\', duration = 3000) => {\n                    if (toastTimer) clearTimeout(toastTimer);\n                    toast.value = { show: true, message: msg, type };\n                    toastTimer = setTimeout(() => { toast.value.show = false; }, duration);\n                    nextTick(() => lucide.createIcons());\n                };\n\n                const setLiveVideoRef = (el, idx) => {\n                    if (el) liveVideoRefs.value[idx] = el;\n                };\n\n                const playLive = (idx) => {\n                    activeLiveIdx.value = idx;\n                    const v = liveVideoRefs.value[idx];\n                    if (v) {\n                        v.currentTime = 0;\n                        v.play().catch(() => {});\n                    }\n                };\n\n                const stopLive = (idx) => {\n                    if (activeLiveIdx.value === idx) {\n                        activeLiveIdx.value = null;\n                        const v = liveVideoRefs.value[idx];\n                        if (v) {\n                            v.pause();\n                            v.currentTime = 0;\n                        }\n                    }\n                };\n\n                // CORS 代理网关池\n                const CORS_GATEWAYS = [\n                    (u) => `https://corsproxy.io/?${encodeURIComponent(u)}`,\n                    (u) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,\n                    (u) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(u)}`,\n                ];\n\n                const fetchWithCorsFallback = async (url) => {\n                    for (const gw of CORS_GATEWAYS) {\n                        try {\n                            const target = gw(url);\n                            const res = await fetch(target, { headers: { \'Accept\': \'application/json, text/html, */*\' } });\n                            if (res.ok) {\n                                return await res.text();\n                            }\n                        } catch (e) {\n                            console.warn(`Gateway failed for ${url}:`, e);\n                        }\n                    }\n                    throw new Error(\'网络请求被拦截，请重试\');\n                };\n\n                // 提取 URL\n                const extractUrlFromText = (text) => {\n                    const match = text.match(/https?:\\/\\/[^\\s\\u4e00-\\u9fa5]+/);\n                    return match ? match[0].replace(/[。，；！？)）]+$/, \'\') : null;\n                };\n\n                // 核心解析逻辑\n                const parseUrlClientSide = async (rawUrl) => {\n                    const cleanUrl = extractUrlFromText(rawUrl);\n                    if (!cleanUrl) throw new Error(\'未检测到有效的分享链接\');\n\n                    if (cleanUrl.includes(\'douyin.com\') || cleanUrl.includes(\'iesdouyin.com\')) {\n                        return await parseDouyin(cleanUrl);\n                    } else if (cleanUrl.includes(\'kuaishou.com\') || cleanUrl.includes(\'kwai.com\')) {\n                        return await parseKuaishou(cleanUrl);\n                    } else {\n                        throw new Error(\'目前支持抖音与快手平台的内容解析\');\n                    }\n                };\n\n                // 抖音解析算法\n                const parseDouyin = async (url) => {\n                    statusMsg.value = \'正在解析抖音作品源信息...\';\n                    const html = await fetchWithCorsFallback(url);\n                    \n                    let awemeId = null;\n                    const idMatch = html.match(/\\/video\\/(\\d+)/) || html.match(/\\/note\\/(\\d+)/) || html.match(/awemeId[\'"]?\\s*:\\s*[\'"]?(\\d+)/) || html.match(/"aweme_id"\\s*:\\s*"(\\d+)"/);\n                    if (idMatch) {\n                        awemeId = idMatch[1];\n                    }\n\n                    if (!awemeId) {\n                        const directMatch = url.match(/\\/(\\d{15,})/);\n                        if (directMatch) awemeId = directMatch[1];\n                    }\n\n                    if (!awemeId) {\n                        throw new Error(\'无法获取抖音作品编号，链接可能已过期或私密\');\n                    }\n\n                    const apiUrl = `https://www.iesdouyin.com/web/api/v2/aweme/iteminfo/?item_ids=${awemeId}`;\n                    const jsonText = await fetchWithCorsFallback(apiUrl);\n                    let item = null;\n                    try {\n                        const data = JSON.parse(jsonText);\n                        if (data.item_list && data.item_list.length > 0) {\n                            item = data.item_list[0];\n                        }\n                    } catch (e) {}\n\n                    if (!item) {\n                        const webApi = `https://www.douyin.com/aweme/v1/web/aweme/detail/?aweme_id=${awemeId}&aid=6383&device_platform=webapp`;\n                        const res2 = await fetchWithCorsFallback(webApi);\n                        const data2 = JSON.parse(res2);\n                        item = data2.aweme_detail;\n                    }\n\n                    if (!item) throw new Error(\'获取抖音作品详情失败\');\n\n                    const desc = item.desc || \'抖音作品\';\n                    const author = {\n                        nickname: item.author?.nickname || \'抖音用户\',\n                        uid: item.author?.unique_id || item.author?.short_id || item.author?.uid || \'\',\n                        avatar: item.author?.avatar_thumb?.url_list?.[0] || item.author?.avatar_medium?.url_list?.[0] || \'\'\n                    };\n                    const stats = {\n                        likes: item.statistics?.digg_count || 0,\n                        comments: item.statistics?.comment_count || 0,\n                        collects: item.statistics?.collect_count || 0\n                    };\n\n                    const images = item.images || [];\n                    const livePhotos = [];\n                    let hasLive = false;\n                    const imageUrls = [];\n\n                    if (images.length > 0) {\n                        images.forEach((img, idx) => {\n                            const uList = img.url_list || img.download_url_list || [];\n                            const u = uList[uList.length - 1] || uList[0];\n                            \n                            let clipUrl = null;\n                            const clips = img.clip_video_list || img.video_list || [];\n                            if (clips.length > 0) {\n                                clipUrl = clips[0].main_url || clips[0].play_addr?.url_list?.[0] || clips[0];\n                                hasLive = true;\n                            }\n\n                            if (u) {\n                                imageUrls.push(u);\n                                livePhotos.push({\n                                    imageUrl: u,\n                                    videoUrl: clipUrl\n                                });\n                            }\n                        });\n                    }\n\n                    const video = item.video;\n                    const qualities = [];\n                    let mainVideoUrl = null;\n\n                    if (video) {\n                        const bitrates = video.bit_rate || [];\n                        bitrates.forEach(b => {\n                            const urls = b.play_addr?.url_list || [];\n                            if (urls.length) {\n                                const clean = urls[0].replace(\'playwm\', \'play\');\n                                const w = b.width || 0;\n                                const h = b.height || 0;\n                                const maxDim = Math.max(w, h);\n                                let label = \'1080P 超清\';\n                                if (maxDim >= 3840 || (b.gear_name && b.gear_name.includes(\'4k\'))) label = \'4K 超清原画\';\n                                else if (maxDim >= 2560) label = \'2K 极清\';\n                                else if (maxDim >= 1920) label = \'1080P 60FPS 原画\';\n                                else if (maxDim >= 1280) label = \'720P 高清\';\n\n                                qualities.push({ label, url: clean, width: w, height: h });\n                            }\n                        });\n\n                        if (!qualities.length && video.play_addr?.url_list?.length) {\n                            const clean = video.play_addr.url_list[0].replace(\'playwm\', \'play\');\n                            qualities.push({ label: \'超清 原画\', url: clean });\n                        }\n\n                        if (qualities.length) {\n                            mainVideoUrl = qualities[0].url;\n                        }\n                    }\n\n                    const mediaType = hasLive ? \'live_photo\' : (imageUrls.length > 0 ? \'images\' : \'video\');\n\n                    return {\n                        platform: \'douyin\',\n                        platformName: \'抖音\',\n                        itemId: awemeId,\n                        title: desc,\n                        author,\n                        stats,\n                        mediaType,\n                        videoUrl: mainVideoUrl,\n                        qualities,\n                        images: imageUrls,\n                        livePhotos,\n                        musicUrl: item.music?.play_url?.url_list?.[0],\n                        musicTitle: item.music?.title,\n                        musicAuthor: item.music?.author,\n                        coverUrl: video?.cover?.url_list?.[0] || imageUrls[0]\n                    };\n                };\n\n                // 快手解析算法\n                const parseKuaishou = async (url) => {\n                    statusMsg.value = \'正在解析快手作品信息...\';\n                    const html = await fetchWithCorsFallback(url);\n\n                    let photoUrl = null;\n                    let title = \'快手作品\';\n                    let author = { nickname: \'快手用户\', avatar: \'\', uid: \'\' };\n                    let images = [];\n\n                    const stateMatch = html.match(/window\\.(?:INIT_STATE|PAGE_DATA|__APOLLO_STATE__)\\s*=\\s*({.+?});?<\\/script>/);\n                    if (stateMatch) {\n                        try {\n                            const data = JSON.parse(stateMatch[1]);\n                            const photo = data.photo || data.photoDetail?.photo || data.video || {};\n                            photoUrl = photo.photoUrl || photo.mainMvUrls?.[0]?.url;\n                            title = photo.caption || title;\n                            author.nickname = photo.userName || author.nickname;\n                            author.avatar = photo.headUrl || \'\';\n                            author.uid = photo.userId || \'\';\n                            \n                            if (photo.ext_params?.atlas) {\n                                const cdn = photo.ext_params.atlas.cdn?.[0] || \'p1.a.yximgs.com\';\n                                images = (photo.ext_params.atlas.list || []).map(p => p.startsWith(\'http\') ? p : `https://${cdn}${p}`);\n                            }\n                        } catch (e) {}\n                    }\n\n                    if (!photoUrl && !images.length) {\n                        const mVideo = html.match(/"photoUrl"\\s*:\\s*"(https?:[^"]+)"/);\n                        if (mVideo) photoUrl = mVideo[1].replace(/\\\\u002F/g, \'/\');\n                    }\n\n                    if (!photoUrl && !images.length) {\n                        throw new Error(\'快手内容提取失败，可能已被删除或私密\');\n                    }\n\n                    const qualities = photoUrl ? [{ label: \'原画 超清\', url: photoUrl }] : [];\n\n                    return {\n                        platform: \'kuaishou\',\n                        platformName: \'快手\',\n                        itemId: \'ks_\' + Date.now(),\n                        title,\n                        author,\n                        stats: { likes: 0, comments: 0, collects: 0 },\n                        mediaType: images.length ? \'images\' : \'video\',\n                        videoUrl: photoUrl,\n                        qualities,\n                        images,\n                        livePhotos: images.map(img => ({ imageUrl: img, videoUrl: null })),\n                        musicUrl: null,\n                        coverUrl: images[0] || \'\'\n                    };\n                };\n\n                // 执行单链接解析\n                const handleParse = async () => {\n                    if (!inputUrl.value.trim()) {\n                        showToast(\'请先输入或粘贴分享链接\', \'error\');\n                        return;\n                    }\n                    isParsing.value = true;\n                    result.value = null;\n                    statusMsg.value = \'正在连接解析源...\';\n\n                    try {\n                        const data = await parseUrlClientSide(inputUrl.value.trim());\n                        result.value = data;\n                        if (data.qualities && data.qualities.length > 0) {\n                            selectedQuality.value = data.qualities[0];\n                        }\n                        saveToHistory(data);\n                        showToast(`解析成功: ${data.title.slice(0, 15)}...`, \'success\');\n                        \n                        if (window.confetti) {\n                            confetti({ particleCount: 60, spread: 60, origin: { y: 0.8 } });\n                        }\n\n                        nextTick(() => {\n                            lucide.createIcons();\n                            const el = document.getElementById(\'result-container\');\n                            if (el) el.scrollIntoView({ behavior: \'smooth\' });\n                        });\n                    } catch (err) {\n                        showToast(err.message || \'解析失败，请检查链接后重试\', \'error\', 4500);\n                    } finally {\n                        isParsing.value = false;\n                        statusMsg.value = \'\';\n                    }\n                };\n\n                // 批量解析\n                const handleBatchParse = async () => {\n                    const text = batchText.value.trim();\n                    if (!text) {\n                        showToast(\'请粘贴包含多个链接的文本\', \'error\');\n                        return;\n                    }\n                    const urlMatches = text.match(/https?:\\/\\/[^\\s\\u4e00-\\u9fa5]+/g) || [];\n                    if (!urlMatches.length) {\n                        showToast(\'未从文本中提取到链接\', \'error\');\n                        return;\n                    }\n\n                    isParsing.value = true;\n                    batchResults.value = [];\n                    statusMsg.value = `共提取到 ${urlMatches.length} 条链接，正在并发解析中...`;\n\n                    const results = [];\n                    for (const u of urlMatches.slice(0, 15)) {\n                        try {\n                            const parsed = await parseUrlClientSide(u);\n                            results.push(parsed);\n                            saveToHistory(parsed);\n                        } catch (e) {\n                            console.warn(\'Batch item failed:\', u, e);\n                        }\n                    }\n\n                    batchResults.value = results;\n                    isParsing.value = false;\n                    statusMsg.value = \'\';\n                    showToast(`批量解析完成：成功 ${results.length} / ${urlMatches.length} 个`, \'success\');\n                    nextTick(() => lucide.createIcons());\n                };\n\n                // 客户端直接下载文件\n                const downloadFile = async (url, filename = \'download.mp4\') => {\n                    if (!url) return;\n                    showToast(\'已开始极速下载...\', \'info\');\n\n                    try {\n                        const res = await fetch(url, { referrerPolicy: \'no-referrer\' });\n                        if (res.ok) {\n                            const blob = await res.blob();\n                            const blobUrl = window.URL.createObjectURL(blob);\n                            const a = document.createElement(\'a\');\n                            a.href = blobUrl;\n                            a.download = filename;\n                            document.body.appendChild(a);\n                            a.click();\n                            document.body.removeChild(a);\n                            window.URL.revokeObjectURL(blobUrl);\n                            showToast(\'下载完成！\', \'success\');\n                            return;\n                        }\n                    } catch (e) {}\n\n                    const a = document.createElement(\'a\');\n                    a.href = url;\n                    a.target = \'_blank\';\n                    a.rel = \'noreferrer\';\n                    a.download = filename;\n                    document.body.appendChild(a);\n                    a.click();\n                    document.body.removeChild(a);\n                };\n\n                // 客户端纯内存打包 ZIP\n                const downloadPackZip = async (item) => {\n                    if (!item) return;\n                    isZipping.value = true;\n                    showToast(\'正在打包全套原图与实况视频，请稍候...\', \'info\', 6000);\n\n                    try {\n                        const zip = new JSZip();\n                        const prefix = `[${item.platformName}]_${item.author?.nickname || \'作品\'}`;\n\n                        if (item.mediaType === \'live_photo\' && item.livePhotos?.length) {\n                            for (let i = 0; i < item.livePhotos.length; i++) {\n                                const lp = item.livePhotos[i];\n                                const num = String(i + 1).padStart(2, \'0\');\n                                \n                                if (lp.imageUrl) {\n                                    try {\n                                        const res = await fetch(lp.imageUrl, { referrerPolicy: \'no-referrer\' });\n                                        const blob = await res.blob();\n                                        zip.file(`${num}_静态原图.jpg`, blob);\n                                    } catch (e) {}\n                                }\n                                if (lp.videoUrl) {\n                                    try {\n                                        const res = await fetch(lp.videoUrl, { referrerPolicy: \'no-referrer\' });\n                                        const blob = await res.blob();\n                                        zip.file(`${num}_实况动态视频.mp4`, blob);\n                                    } catch (e) {}\n                                }\n                            }\n                        } else if (item.images?.length) {\n                            for (let i = 0; i < item.images.length; i++) {\n                                const num = String(i + 1).padStart(2, \'0\');\n                                try {\n                                    const res = await fetch(item.images[i], { referrerPolicy: \'no-referrer\' });\n                                    const blob = await res.blob();\n                                    zip.file(`${num}_高清原图.jpg`, blob);\n                                } catch (e) {}\n                            }\n                        }\n\n                        const content = await zip.generateAsync({ type: \'blob\' });\n                        const blobUrl = window.URL.createObjectURL(content);\n                        const a = document.createElement(\'a\');\n                        a.href = blobUrl;\n                        a.download = `${prefix}_打包合集.zip`;\n                        document.body.appendChild(a);\n                        a.click();\n                        document.body.removeChild(a);\n                        window.URL.revokeObjectURL(blobUrl);\n                        showToast(\'ZIP 压缩包生成完成！\', \'success\');\n                    } catch (err) {\n                        showToast(\'打包失败: \' + err.message, \'error\');\n                    } finally {\n                        isZipping.value = false;\n                    }\n                };\n\n                const pasteClipboard = async () => {\n                    try {\n                        if (navigator.clipboard?.readText) {\n                            const text = await navigator.clipboard.readText();\n                            if (text) {\n                                if (tab.value === \'single\') inputUrl.value = text;\n                                else batchText.value = text;\n                                showToast(\'已从剪贴板粘贴\', \'success\');\n                            }\n                        } else {\n                            showToast(\'请直接按 Ctrl+V 粘贴\', \'info\');\n                        }\n                    } catch (e) {\n                        showToast(\'无法访问剪贴板，请手动粘贴\', \'info\');\n                    }\n                };\n\n                const copyLink = (text) => {\n                    if (!text) return;\n                    navigator.clipboard?.writeText(text).then(() => {\n                        showToast(\'直链已复制到剪贴板\', \'success\');\n                    }).catch(() => {\n                        showToast(\'复制失败\', \'error\');\n                    });\n                };\n\n                const saveToHistory = (item) => {\n                    if (!item) return;\n                    historyList.value = historyList.value.filter(h => h.itemId !== item.itemId);\n                    historyList.value.unshift({\n                        ...item,\n                        savedAt: new Date().toLocaleTimeString()\n                    });\n                    if (historyList.value.length > 30) historyList.value.pop();\n                    try {\n                        localStorage.setItem(\'omnimedia_standalone_hist\', JSON.stringify(historyList.value));\n                    } catch (e) {}\n                };\n\n                const loadHistory = () => {\n                    try {\n                        const saved = localStorage.getItem(\'omnimedia_standalone_hist\');\n                        if (saved) historyList.value = JSON.parse(saved);\n                        const savedTheme = localStorage.getItem(\'omnimedia_theme\');\n                        if (savedTheme) setTheme(savedTheme);\n                    } catch (e) {}\n                };\n\n                const clearHistory = () => {\n                    historyList.value = [];\n                    localStorage.removeItem(\'omnimedia_standalone_hist\');\n                    showToast(\'历史记录已清空\', \'info\');\n                };\n\n                const loadFromHistory = (item) => {\n                    result.value = item;\n                    if (item.qualities?.length) selectedQuality.value = item.qualities[0];\n                    showHistory.value = false;\n                    tab.value = \'single\';\n                    nextTick(() => {\n                        lucide.createIcons();\n                        const el = document.getElementById(\'result-container\');\n                        if (el) el.scrollIntoView({ behavior: \'smooth\' });\n                    });\n                };\n\n                const viewBatchItem = (item) => {\n                    result.value = item;\n                    if (item.qualities?.length) selectedQuality.value = item.qualities[0];\n                    nextTick(() => {\n                        lucide.createIcons();\n                        const el = document.getElementById(\'result-container\');\n                        if (el) el.scrollIntoView({ behavior: \'smooth\' });\n                    });\n                };\n\n                const openLightbox = (imgs, idx = 0) => {\n                    lightbox.value.images = imgs;\n                    lightbox.value.index = idx;\n                    lightbox.value.show = true;\n                    nextTick(() => lucide.createIcons());\n                };\n\n                const lightboxPrev = () => {\n                    if (lightbox.value.index > 0) lightbox.value.index--;\n                    else lightbox.value.index = lightbox.value.images.length - 1;\n                };\n\n                const lightboxNext = () => {\n                    if (lightbox.value.index < lightbox.value.images.length - 1) lightbox.value.index++;\n                    else lightbox.value.index = 0;\n                };\n\n                const formatNumber = (num) => {\n                    if (!num) return 0;\n                    if (num >= 10000) return (num / 10000).toFixed(1) + \'w\';\n                    return num;\n                };\n\n                const getMediaTypeBadge = (res) => {\n                    if (res.mediaType === \'live_photo\') return \'实况照片 Live Photo\';\n                    if (res.mediaType === \'images\') return `高清图集 (${res.images.length}张)`;\n                    return \'4K/高清视频\';\n                };\n\n                onMounted(() => {\n                    loadHistory();\n                    lucide.createIcons();\n                });\n\n                return {\n                    currentTheme,\n                    themeOptions,\n                    setTheme,\n                    tab,\n                    inputUrl,\n                    batchText,\n                    isParsing,\n                    statusMsg,\n                    result,\n                    selectedQuality,\n                    batchResults,\n                    isZipping,\n                    showHistory,\n                    showHelp,\n                    historyList,\n                    activeLiveIdx,\n                    lightbox,\n                    toast,\n                    setLiveVideoRef,\n                    playLive,\n                    stopLive,\n                    handleParse,\n                    handleBatchParse,\n                    downloadFile,\n                    downloadPackZip,\n                    pasteClipboard,\n                    copyLink,\n                    clearHistory,\n                    loadFromHistory,\n                    viewBatchItem,\n                    openLightbox,\n                    lightboxPrev,\n                    lightboxNext,\n                    formatNumber,\n                    getMediaTypeBadge\n                };\n            }\n        }).mount(\'#app\');\n    </script>\n</body>\n</html>\n'
